import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { tasksAPI, goalsAPI } from '../utils/api';
import { CheckSquare, Target, Calendar, TrendingUp, BookOpen, Plus, Zap, Star, Trophy, Clock, ArrowRight } from 'lucide-react';

const Dashboard = () => {
  const { user } = useAuth();
  const [stats, setStats] = useState({
    tasks: { total: 0, completed: 0, pending: 0 },
    goals: { total: 0, completed: 0 }
  });
  const [recentTasks, setRecentTasks] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      // Mock data for demo
      setStats({
        tasks: { total: 12, completed: 8, pending: 4, inProgress: 2 },
        goals: { total: 5, completed: 2 }
      });

      setRecentTasks([
        { _id: '1', title: 'Complete project proposal', dueDate: new Date(), status: 'in-progress', priority: 'high' },
        { _id: '2', title: 'Review team feedback', dueDate: new Date(), status: 'pending', priority: 'medium' },
        { _id: '3', title: 'Update documentation', dueDate: new Date(), status: 'completed', priority: 'low' }
      ]);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const quickActions = [
    {
      title: 'Create Task',
      icon: <CheckSquare className="w-6 h-6" />,
      link: '/tasks',
      gradient: 'from-emerald-500 to-teal-600',
      description: 'Add a new task to your list'
    },
    {
      title: 'Set Goal',
      icon: <Target className="w-6 h-6" />,
      link: '/goals',
      gradient: 'from-blue-500 to-indigo-600',
      description: 'Define your next milestone'
    },
    {
      title: 'View Calendar',
      icon: <Calendar className="w-6 h-6" />,
      link: '/calendar',
      gradient: 'from-violet-500 to-purple-600',
      description: 'Check your schedule'
    },
    {
      title: 'Write Entry',
      icon: <BookOpen className="w-6 h-6" />,
      link: '/diary',
      gradient: 'from-orange-500 to-amber-600',
      description: 'Capture your thoughts'
    }
  ];

  const statCards = [
    {
      title: 'Total Tasks',
      value: stats.tasks.total,
      icon: <CheckSquare className="w-8 h-8" />,
      gradient: 'from-emerald-500 to-teal-600',
      change: '+12%',
      changeType: 'positive'
    },
    {
      title: 'Completed',
      value: stats.tasks.completed,
      icon: <Trophy className="w-8 h-8" />,
      gradient: 'from-blue-500 to-indigo-600',
      change: '+8%',
      changeType: 'positive'
    },
    {
      title: 'Active Goals',
      value: stats.goals.total - stats.goals.completed,
      icon: <Target className="w-8 h-8" />,
      gradient: 'from-violet-500 to-purple-600',
      change: '+3%',
      changeType: 'positive'
    },
    {
      title: 'Success Rate',
      value: `${stats.tasks.total > 0 ? Math.round((stats.tasks.completed / stats.tasks.total) * 100) : 0}%`,
      icon: <TrendingUp className="w-8 h-8" />,
      gradient: 'from-orange-500 to-amber-600',
      change: '+15%',
      changeType: 'positive'
    }
  ];

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 via-white to-gray-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 flex items-center justify-center">
        <div className="relative">
          <div className="w-20 h-20 border-4 border-gray-200 dark:border-gray-700 rounded-full animate-spin"></div>
          <div className="absolute top-0 left-0 w-20 h-20 border-4 border-transparent border-t-emerald-500 rounded-full animate-spin"></div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-white to-gray-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 pt-24">
      <div className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8">
        {/* Welcome Section */}
        <div className="mb-12 animate-fade-in-up">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-4xl md:text-5xl font-black text-transparent bg-clip-text bg-gradient-to-r from-gray-900 via-emerald-700 to-blue-700 dark:from-white dark:via-emerald-300 dark:to-blue-300 mb-2">
                Welcome back, {user?.name}! 👋
              </h1>
              <p className="text-xl text-gray-600 dark:text-gray-400">
                Ready to make today amazing? Let's check your progress.
              </p>
            </div>
            <div className="hidden md:flex items-center space-x-2 text-sm text-gray-500 dark:text-gray-400">
              <Clock className="w-4 h-4" />
              <span>{new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</span>
            </div>
          </div>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
          {statCards.map((card, index) => (
            <div
              key={index}
              className={`group relative p-6 bg-white dark:bg-gray-800 rounded-3xl shadow-lg hover:shadow-2xl border border-gray-200 dark:border-gray-700 transition-all duration-500 hover:scale-105 animate-fade-in-up`}
              style={{ animationDelay: `${index * 100}ms` }}
            >
              <div className="flex items-center justify-between mb-4">
                <div className={`p-3 bg-gradient-to-r ${card.gradient} rounded-2xl text-white group-hover:scale-110 transition-transform duration-300`}>
                  {card.icon}
                </div>
                <div className={`text-sm font-semibold px-2 py-1 rounded-full ${
                  card.changeType === 'positive' 
                    ? 'text-emerald-600 bg-emerald-100 dark:text-emerald-400 dark:bg-emerald-900/30' 
                    : 'text-red-600 bg-red-100 dark:text-red-400 dark:bg-red-900/30'
                }`}>
                  {card.change}
                </div>
              </div>

              <div>
                <p className="text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">{card.title}</p>
                <p className="text-3xl font-black text-gray-900 dark:text-white">{card.value}</p>
              </div>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Quick Actions */}
          <div className="lg:col-span-1 animate-slide-in-left">
            <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg p-8 border border-gray-200 dark:border-gray-700">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Quick Actions</h2>
                <Zap className="w-6 h-6 text-amber-500" />
              </div>

              <div className="space-y-4">
                {quickActions.map((action, index) => (
                  <Link
                    key={index}
                    to={action.link}
                    className="group flex items-center p-4 rounded-2xl hover:bg-gray-50 dark:hover:bg-gray-700 transition-all duration-300 transform hover:scale-105"
                  >
                    <div className={`p-3 rounded-xl bg-gradient-to-r ${action.gradient} text-white mr-4 group-hover:scale-110 transition-transform duration-300`}>
                      {action.icon}
                    </div>
                    <div className="flex-1">
                      <h3 className="font-semibold text-gray-900 dark:text-white group-hover:text-transparent group-hover:bg-clip-text group-hover:bg-gradient-to-r group-hover:from-emerald-600 group-hover:to-blue-600 transition-all duration-300">
                        {action.title}
                      </h3>
                      <p className="text-sm text-gray-600 dark:text-gray-400">{action.description}</p>
                    </div>
                    <ArrowRight className="w-5 h-5 text-gray-400 group-hover:text-emerald-500 group-hover:translate-x-1 transition-all duration-300" />
                  </Link>
                ))}
              </div>
            </div>
          </div>

          {/* Recent Tasks */}
          <div className="lg:col-span-2 animate-slide-in-right">
            <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg p-8 border border-gray-200 dark:border-gray-700">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Recent Tasks</h2>
                <Link
                  to="/tasks"
                  className="flex items-center text-emerald-600 dark:text-emerald-400 hover:text-emerald-700 dark:hover:text-emerald-300 font-medium group"
                >
                  View all
                  <ArrowRight className="w-4 h-4 ml-1 group-hover:translate-x-1 transition-transform" />
                </Link>
              </div>

              {recentTasks.length > 0 ? (
                <div className="space-y-4">
                  {recentTasks.map((task, index) => (
                    <div
                      key={task._id}
                      className="group flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-2xl border border-gray-200 dark:border-gray-600 hover:bg-gray-100 dark:hover:bg-gray-600 transition-all duration-300 animate-fade-in-up"
                      style={{ animationDelay: `${index * 100}ms` }}
                    >
                      <div className="flex items-center space-x-4">
                        <div className={`w-4 h-4 rounded-full ${
                          task.status === 'completed' ? 'bg-emerald-500' :
                          task.status === 'in-progress' ? 'bg-amber-500' : 'bg-gray-400'
                        } group-hover:scale-125 transition-transform duration-300`}></div>

                        <div>
                          <h3 className="font-semibold text-gray-900 dark:text-white group-hover:text-transparent group-hover:bg-clip-text group-hover:bg-gradient-to-r group-hover:from-emerald-600 group-hover:to-blue-600 transition-all duration-300">
                            {task.title}
                          </h3>
                          <p className="text-sm text-gray-600 dark:text-gray-400">
                            Due: {new Date(task.dueDate).toLocaleDateString()}
                          </p>
                        </div>
                      </div>

                      <div className="flex items-center space-x-3">
                        <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                          task.priority === 'high' ? 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300' :
                          task.priority === 'medium' ? 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300' :
                          'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-300'
                        }`}>
                          {task.priority}
                        </span>

                        {task.status === 'completed' && (
                          <Star className="w-5 h-5 text-amber-500 animate-pulse" />
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-12">
                  <div className="w-20 h-20 bg-gradient-to-r from-emerald-500 to-blue-600 rounded-full flex items-center justify-center mx-auto mb-4 animate-float">
                    <CheckSquare className="w-10 h-10 text-white" />
                  </div>
                  <h3 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">No tasks yet!</h3>
                  <p className="text-gray-600 dark:text-gray-400 mb-6">Create your first task to get started on your productivity journey.</p>
                  <Link
                    to="/tasks"
                    className="inline-flex items-center px-6 py-3 bg-gradient-to-r from-emerald-500 to-blue-600 text-white rounded-xl font-semibold hover:from-emerald-400 hover:to-blue-500 transition-all duration-300 transform hover:scale-105 hover:shadow-lg"
                  >
                    <Plus className="w-5 h-5 mr-2" />
                    Create Task
                  </Link>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Motivational Quote */}
        <div className="mt-12 animate-fade-in-up delay-600">
          <div className="relative p-8 bg-gradient-to-r from-emerald-500/10 to-blue-600/10 rounded-3xl border border-emerald-200 dark:border-emerald-800 overflow-hidden">
            <div className="absolute inset-0 bg-gradient-to-r from-emerald-500/5 to-blue-600/5 animate-pulse"></div>
            <div className="relative text-center">
              <h3 className="text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-emerald-600 to-blue-600 mb-2">
                "Success is the sum of small efforts repeated day in and day out."
              </h3>
              <p className="text-gray-600 dark:text-gray-400">- Robert Collier</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
